mapper.select:
SELECT COALESCE(t.status, 'UNKNOWN') AS status, COUNT(*) AS count
FROM oa_attendance t
WHERE t.deleted = 0
  AND t.attendance_date >= #{start}
  AND t.attendance_date <= #{end}

GROUP BY t.status

SELECT COALESCE(SUM(t.duration), 0) FROM oa_leave t
WHERE t.deleted = 0
  AND t.status = 'APPROVED'
  AND t.start_time >= #{start}
  AND t.start_time <= #{end}

SELECT COUNT(*) FROM oa_leave t
WHERE t.deleted = 0
  AND t.status = 'APPROVED'
  AND t.start_time >= #{start}
  AND t.start_time <= #{end}
